mapper.select:
SELECT COALESCE(MAX(reassignment_no), 0)
FROM cut_approval_reassignment
WHERE tenant_id = #{query.tenantId}
  AND approval_instance_id = #{query.approvalInstanceId}
  AND approval_node_id = (
    SELECT id FROM cut_approval_node
    WHERE tenant_id = #{query.tenantId}
      AND approval_instance_id = #{query.approvalInstanceId}
      AND node_no = #{query.nodeNo}
      AND deleted = b'0')
  AND deleted = b'0'
